from .repository import balance, begin, move


def _require_positive_int(amount):
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise ValueError("amount must be a positive integer")
    if amount <= 0:
        raise ValueError("amount must be a positive integer")


def transfer(connection, publisher, source, target, amount):
    _require_positive_int(amount)
    if source == target:
        raise ValueError("source and target must differ")

    # Nothing is written before this point, so a failure to start the
    # transaction leaves the database untouched and nothing is published.
    begin(connection)
    try:
        source_balance = balance(connection, source)
        if source_balance is None:
            raise ValueError(f"unknown source account: {source!r}")
        if balance(connection, target) is None:
            raise ValueError(f"unknown target account: {target!r}")
        if amount > source_balance:
            raise ValueError("amount exceeds source balance")
        move(connection, source, target, amount)
        connection.commit()
    except BaseException:
        # Covers both invalid transfers and database failures at any
        # statement or at commit. Undo everything and re-raise without
        # publishing.
        connection.rollback()
        raise

    # Publication happens only after a successful commit. A failure here
    # propagates to the caller but does not undo the committed transfer.
    publisher.publish({"source": source, "target": target, "amount": amount})
